authoritative_observation:
{
  "case_id": "old_paper_umbrella",
  "title": "旧纸伞与失约书生",
  "synopsis": "一名书生连续梦见窗外有人呼名，影子渐淡，并开始遗忘亲人的面容。玩家需与调查搭档核对人物、契物与承诺之间的联系。",
  "patient_id": "scholar_lu",
  "patient_name": "陆砚生",
  "patient_public_profile": "寄居镇中备考的年轻书生，自称近日只是睡眠不安。",
  "session_status": "active",
  "session_revision": 0,
  "discovered_clues": [],
  "available_investigations": [
    {
      "investigation_id": "ask_about_memory",
      "action_type": "question_patient",
      "target_id": "scholar_lu",
      "public_description": "询问书生近期睡眠、记忆和日常经历的变化。"
    },
    {
      "investigation_id": "inspect_umbrella",
      "action_type": "inspect_object",
      "target_id": "old_paper_umbrella",
      "public_description": "检查旧纸伞的破损、水迹、伞柄和异常痕迹。"
    },
    {
      "investigation_id": "observe_scholar",
      "action_type": "observe_patient",
      "target_id": "scholar_lu",
      "public_description": "观察书生的神色、动作、影子与周围灯火表现。"
    }
  ],
  "diagnosis_candidates": [
    {
      "diagnosis_id": "evil_spirit_attack",
      "public_description": "有外来灵体主动侵袭书生，旧纸伞只是异常力量附着的媒介。"
    },
    {
      "diagnosis_id": "exam_exhaustion",
      "public_description": "长期备考和睡眠紊乱使书生心神衰弱，所见异常可能主要源于疲惫。"
    },
    {
      "diagnosis_id": "rain_vow_breach",
      "public_description": "书生与旧伞相关的一项雨夜承诺尚未履行，异常可能来自未闭合的契约。"
    }
  ],
  "can_submit_diagnosis": true,
  "submitted_diagnosis_id": null,
  "available_treatments": []
}
